___CSS_LOADER_EXPORT___.push([module.id, "h4[data-v-a2206fd6]{text-align:center}p[data-v-a2206fd6]{color:#565656;padding:20px 15px;text-align:left}.memm_table[data-v-a2206fd6],p[data-v-a2206fd6]{font-size:12px}.memm_table[data-v-a2206fd6]{padding:0 15px;width:100%}.memm_table th[data-v-a2206fd6]{background:#fafafa;border-bottom:1px solid #e4e4e4;border-top:2px solid #d6d6d6;color:#666;padding:10px 0;text-align:center}.memm_table td[data-v-a2206fd6]{border-bottom:1px solid #e6e6e6;border-left:1px solid #e6e6e6;padding:10px;text-align:center;vertical-align:top}.memm_table td[data-v-a2206fd6]:first-child{border-left:0}.memm_table td.leftb[data-v-a2206fd6]{border-left:1px solid #e6e6e6}", "",{"version":3,"sources":["webpack://./resources/js/views/web/auth/_comp/Marketing.vue"],"names":[],"mappings":"AAsDA,oBAAA,iBAAA,CACA,mBAAA,aAAA,CAAA,iBAAA,CAAA,eAAA,CACA,gDADA,cACA,CAAA,6BAAA,cAAA,CAAA,UAAA,CACA,gCAAA,kBAAA,CAAA,+BAAA,CAAA,4BAAA,CAAA,UAAA,CAAA,cAAA,CAAA,iBAAA,CACA,gCAAA,+BAAA,CAAA,6BAAA,CAAA,YAAA,CAAA,iBAAA,CAAA,kBAAA,CACA,4CAAA,aAAA,CACA,sCAAA,6BAAA","sourcesContent":["<template>\r\n<div>\r\n    <h4>(선택) (주)아이넥서스 마케팅 활용</h4>\r\n    <p>\r\n        <strong style=\"color:#f24638 ;\">본 내용의 동의여부는 회원가입에 어떠한 영향도 미치지 않습니다.</strong><br>\r\n\r\n        <strong>개인정보의 제공에 관한 사</strong>항<br><br>\r\n\r\n        <strong>개인정보의 사용 및 제3자에 대한 제공</strong><br>\r\n        가. 회사는 이용자의 개인정보를 「개인정보의 수집 및 이용」에서 고지한 범위 내에서 사용하며, 이용자의 동의 없이 동 범위를 초과하여 이용하거나 원칙적으로 이용자의 개인정보를 제3자에게 제공하지 않습니다.<br><br>\r\n\r\n        다만, 아래의 경우에는 예외로 합니다.<br>\r\n        1) 이용자들이 사전에 공개 또는 제3자 제공에 동의한 경우<br>\r\n        2) 법령의 규정에 의거하거나, 수사, 조사 목적으로 법령에 정해진 절차와 방법에 따라 수사기관 및 감독당국의 요구가 있는 경우<br><br>\r\n\r\n        나. 회사는 수집된 이메일 주소, 전화번호,주소 항목을 활용하여 정기/비정기 쇼핑레터, 새로운 서비스/신상품 안내, 전화 연락 등의 수단으로 안내하고 있습니다.<br>\r\n        단, 견적서 제공과 주문 및 1:1문의, 주문제품의 배송안내 등 과 관련한 내용은 본 동의 여부와 상관없이 받아보실 수 있습니다.<br>\r\n        4science에서 진행하는 이벤트 참여를 통해 경품/사은품 발송 시 개인정보는 제 3자에게 제공되지 않습니다.<br>\r\n        다만, 외부 업체 주관행사를 통해 경품/사은품 발송 시 회원정보(이름, 연락처, 주소)가 제공 될 수 있습니다.<br>\r\n        본 동의는 언제든지 전화와 팩스 등을 통하여 본인 확인 후 동의 여부 변경 및 철회를 요청 하거나, 마이페이지 &gt; 개인정보수정에서 수단별(E-mail 발송, SMS 발송, 이벤트 참여)등의 여부를 변경 및 철회할 수 있습니다.<br><br>\r\n\r\n        다. 그 밖에 개인정보 제3자제공이 필요한 경우에는 합당한 절차를 통한 이용자의 동의를 얻어 제3자에게 개인정보를 제공 할 수 있습니다.<br>\r\n        동의를 얻어 개인정보를 제공받는 자와 이용목적은 아래와 같습니다.\r\n\r\n    </p>\r\n    <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"memm_table\">\r\n        <colgroup>\r\n            <col style=\"\">\r\n            <col style=\"\">\r\n        <col style=\"width:30%;\">\r\n        <col style=\"width:30%;\">\r\n        <col style=\"width:15%;\">\r\n        </colgroup>\r\n        <thead>\r\n            <tr>\r\n                <th>개인정보를<br>제공받는 자</th>\r\n                <th>개인정보를 제공받는 자의<br>개인정보 이용목적</th>\r\n                <th>제공하는 개인정보의 항목</th>\r\n                <th>개인정보를 제공받는 자의<br>개인정보 보유 및 이용기간</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr>\r\n            <td>이벤트(행사)제안 업체</td>\r\n            <td>이벤트 경품발송</td>\r\n            <td>아이디/이름/성별/주소/전화번호/우편번호</td>\r\n            <td>개인정보를 제공한날로부터 1개월 이내에 삭제</td>\r\n        </tr>\r\n        </tbody>\r\n    </table>\r\n</div>\r\n</template>\r\n<script> export default { name: 'AuthMarketing', }; </script>\r\n<style lang=\"css\" scoped>\r\nh4 { text-align:center; }\r\np { text-align:left; font-size:12px; color:#565656; padding:20px 15px;}\r\n.memm_table { width:100%; font-size:12px; padding:0 15px;}\r\n.memm_table th { padding:10px 0; border-top:2px solid #d6d6d6; border-bottom:1px solid #e4e4e4; text-align:center; background:#fafafa; color:#666; }\r\n.memm_table td { padding:10px; border-left:1px solid #e6e6e6; border-bottom:1px solid #e6e6e6; text-align:center; vertical-align:top; }\r\n.memm_table td:first-child { border-left:0; }\r\n.memm_table td.leftb {border-left:1px solid #e6e6e6;}\r\n</style>"],"sourceRoot":""}]);
